import{_ as a,c as l,g as e,o as n}from"./chunks/framework.CCxIPCIe.js";const m=JSON.parse('{"title":"四三七","description":"","frontmatter":{"title":"四三七","date":"2026-09-27T13:20:08.928Z","length":"1263字","time":"5分钟","aside":false,"hash":-124019193},"headers":[],"relativePath":"idea/437.md","filePath":"idea/437.md"}'),s={name:"idea/437.md"};function p(r,t,o,d,i,u){return n(),l("div",null,t[0]||(t[0]=[e("p",null,"现在流行一个词叫财富自由。人们疲于打工，想从牛马角色中解脱出来，做自己想做的事情。但生活资料并不是免费的，只能通过劳动来换取，但劳动又往往不是自愿的，因而要计划不劳而获，即不需要参加被迫的劳动，就能获得养活自己的资料。",-1),e("p",null,"但是，财富自由是一笔糊涂账。在计算如何才算养活自己的问题上，不同人的想法千差万别。因此，人们很容易迷失在这种算计中，偏离自己的目的。",-1),e("p",null,"我们必须意识到，所谓的财富自由，并不是真正的目的。真正的目的是有能力做自己想做的事并做它。财富自由至多只是一个必要条件，它仅仅是维持生命延续的条件。",-1),e("p",null,"而真正的目的，我们不妨称之为行动自由。行动自由的意涵很多，比如智性能够胜任想做的事情，人脉能够提供必要的帮助，物质条件能够补充前两者无法覆盖的部分。财富自由可以在自由市场中兑换行动自由，但是这种兑换是有限度的，它停留在物质要素上。",-1),e("p",null,"财富自由无法兑换的，是行动者的精神自由。也就是说，那种设定目标并努力实现它的精神动力、生命力。即便财富可以选择雇佣精神为它效劳，雇佣者也没有发挥它的精神自由。因为它把精神的内容扁平化为纯粹的量，在这个过程中，没有精神被对象化到物质层面，反而通过雇佣关系，用物质力束缚了另一个人的精神自由。",-1),e("p",null,"精神自由，就是发挥主观能动性的自由。把不同物质要素堆在一起，并不能让事情自发完成。它们必须通过精神的中介凝结为新的对象。如果我们继续推演下去，就会意识到，任何物质要素，无非都是某种阶段性的原材料经过精神的中介而实现的新对象，因此物质要素的匮乏，或者说财富的匮乏，总是可以通过精神来补足的，只是说在这个过程中，精神需要付出更多的劳动。",-1),e("p",null,"这样就产生了辩证运动。行动自由是为了实现精神设定的某种目的，但是这种目的总是受着这样或那样的局限，无法直接完成。（或者说从来没有直接的目的）一个目的总是要被拆解成不同的环节，然后精神按照自己的财富来选择跳过其中的某些环节，以便集中足够的注意力和生命能量应对真正重要的环节。这种权衡的过程，本身就是一种不自由，也就是说精神为了追求自由，必须将自己委身于某种不自由。或者说精神总是在取舍中看到了这种不自由，但精神取舍的这个行为本身就反映了精神的自由。",-1),e("p",null,"因此我们可以说，要放弃盲目的追求某种绝对的、一劳永逸的财富自由。因为我们必须意识到不自由总是存在的，问题是精神愿意为它付出多少代价。如果为了财富自由，牺牲了身体健康、思维敏锐，它同样限制了行动自由。反过来，要善于运用年轻人最宝贵的身体和精神资源，直接上手去做自己想要做的事，在有限资源的条件下，学会取舍、锻炼自己的行动力。而这种行动力的培养，并不亚于财富积累。后者往往是一种致命的诱惑，它让人忘记了一个道理：你有张良计，我有过墙梯。做任何一件事情，在不同的条件下都有不同的做法。总是试图等到万事俱备，最终会把你的行动欲望消耗殆尽，而一个人的欲望被消耗殆尽最终就表现为欲望能力的匮乏，即它把物欲视为唯一的欲望，因为它完全忘记了自己有直接创造物质的能力，而把金钱的间接兑换视为了全部，也就是说它把自己全部的出卖给金钱，只有这种出卖才能惨烈的实现它的欲望。更可悲的是，它在这种出卖中无限延宕了它真正想做的事，而无法实现生产者的主体性，仅仅沦为消费主义机器中的一个平平无奇的齿轮，任凭金钱平滑的流过，而无法施加任何对象化的劳动，把自己的独特的主体性铭刻在物质中。",-1)]))}const _=a(s,[["render",p]]);export{m as __pageData,_ as default};
